package com.collabboard.entity;
import jakarta.persistence.*;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;import com.fasterxml.jackson.databind.JsonNode;import com.collabboard.auth.AppUser;import java.time.Instant;
@Entity @Table(name="rooms") public class Room {
 @Id @Column(name="room_id",length=36)private String roomId;@Column(nullable=false,length=120)private String title;@JdbcTypeCode(SqlTypes.JSON)@Column(name="board_state",nullable=false,columnDefinition="jsonb")private JsonNode boardState;@Column(nullable=false)private long version;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="owner_id")private AppUser owner;@Column(name="created_at",nullable=false)private Instant createdAt=Instant.now();@Column(name="updated_at",nullable=false)private Instant updatedAt=Instant.now();
 protected Room(){}public Room(String id,String title){roomId=id;this.title=title;}public Room(String id,String title,AppUser owner){this(id,title);this.owner=owner;}public String getRoomId(){return roomId;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public JsonNode getBoardState(){return boardState;}public void setBoardState(JsonNode v){boardState=v;}public long getVersion(){return version;}public void setVersion(long v){version=v;}public AppUser getOwner(){return owner;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}public void touch(){updatedAt=Instant.now();}
}
